insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('Prompt Engineering Fundamentals', 'prompt-engineering-fundamentals', 'Master the core prompting techniques — role, context, constraints and examples — that turn ChatGPT, Claude and Gemini into reliable assistants.', 'Master the core prompting techniques — role, context, constraints and examples — that turn ChatGPT, Claude and Gemini into reliable assistants.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'prompt-engineering-fundamentals'), 'How large language models actually respond to prompts', 'how-large-language-models-actually-respond-to-prompts', '<p>Welcome to <strong>Prompt Engineering Fundamentals</strong>. This opening lesson sets the foundation for everything that follows in the Prompt Engineering track: how large language models actually respond to prompts. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in ChatGPT for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: how large language models actually respond to prompts — explained with worked examples</li><li>A guided walkthrough in ChatGPT</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>The anatomy of a great prompt: role, task, context, format</em>.</p>', null, 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'prompt-engineering-fundamentals'), 'The anatomy of a great prompt: role, task, context, format', 'the-anatomy-of-a-great-prompt-role-task-context-format', '<p>In this lesson we focus on <strong>The anatomy of a great prompt: role, task, context, format</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Claude for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: the anatomy of a great prompt: role, task, context, format — explained with worked examples</li><li>A guided walkthrough in Claude</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Zero-shot vs few-shot: teaching by example</em>.</p>', null, 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'prompt-engineering-fundamentals'), 'Zero-shot vs few-shot: teaching by example', 'zero-shot-vs-few-shot-teaching-by-example', '<p>In this lesson we focus on <strong>Zero-shot vs few-shot: teaching by example</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Gemini for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: zero-shot vs few-shot: teaching by example — explained with worked examples</li><li>A guided walkthrough in Gemini</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Constraints, tone and output formatting that stick</em>.</p>', null, 3);
