insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'prompting-for-business-documents'), 'Document templates you can reuse across clients', 'document-templates-you-can-reuse-across-clients', '<p>In this lesson we focus on <strong>Document templates you can reuse across clients</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in ChatGPT for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: document templates you can reuse across clients — explained with worked examples</li><li>A guided walkthrough in ChatGPT</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — create a complete business proposal pack — executive summary, scope, pricing and SOP — generated and refined entirely through documented prompts. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 7);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('Image Prompting Masterclass', 'image-prompting-masterclass', 'Learn the visual vocabulary — composition, lens, lighting, style references — that gets consistent results from Midjourney, DALL·E and Ideogram.', 'Learn the visual vocabulary — composition, lens, lighting, style references — that gets consistent results from Midjourney, DALL·E and Ideogram.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'image-prompting-masterclass'), 'How diffusion models interpret your words', 'how-diffusion-models-interpret-your-words', '<p>Welcome to <strong>Image Prompting Masterclass</strong>. This opening lesson sets the foundation for everything that follows in the Prompt Engineering track: how diffusion models interpret your words. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in Midjourney for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: how diffusion models interpret your words — explained with worked examples</li><li>A guided walkthrough in Midjourney</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Composition, framing and camera language</em>.</p>', null, 1);
