insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'system-prompts-and-custom-gpts'), 'System prompts vs user prompts: who controls what', 'system-prompts-vs-user-prompts-who-controls-what', '<p>Welcome to <strong>System Prompts &amp; Custom GPTs</strong>. This opening lesson sets the foundation for everything that follows in the Prompt Engineering track: system prompts vs user prompts: who controls what. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in Custom GPTs for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: system prompts vs user prompts: who controls what — explained with worked examples</li><li>A guided walkthrough in Custom GPTs</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Writing persona and policy into a system prompt</em>.</p>', null, 1);
