insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'brand-voice-with-ai'), 'Maintaining voice as your brand evolves', 'maintaining-voice-as-your-brand-evolves', '<p>In this lesson we focus on <strong>Maintaining voice as your brand evolves</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Claude for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: maintaining voice as your brand evolves — explained with worked examples</li><li>A guided walkthrough in Claude</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — create a complete brand voice kit — voice attributes, do/don''t examples, lexicon and master prompt — and prove it on five content types. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 7);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('Long-Form Writing with AI: Guides, Ebooks & Whitepapers', 'long-form-writing-with-ai', 'Co-write substantial long-form pieces — ultimate guides, ebooks, whitepapers — with outlines, research synthesis and chapter-by-chapter drafting.', 'Co-write substantial long-form pieces — ultimate guides, ebooks, whitepapers — with outlines, research synthesis and chapter-by-chapter drafting.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'long-form-writing-with-ai'), 'Choosing topics worth 5,000 words', 'choosing-topics-worth-5-000-words', '<p>Welcome to <strong>Long-Form Writing with AI: Guides, Ebooks &amp; Whitepapers</strong>. This opening lesson sets the foundation for everything that follows in the AI Content &amp; Copywriting track: choosing topics worth 5,000 words. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in Claude for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: choosing topics worth 5,000 words — explained with worked examples</li><li>A guided walkthrough in Claude</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Research synthesis: sources in, structured notes out</em>.</p>', null, 1);
