insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'seo-content-strategy-with-ai'), 'Reporting: what to show stakeholders monthly', 'reporting-what-to-show-stakeholders-monthly', '<p>In this lesson we focus on <strong>Reporting: what to show stakeholders monthly</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in ChatGPT for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: reporting: what to show stakeholders monthly — explained with worked examples</li><li>A guided walkthrough in ChatGPT</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — deliver a 90-day SEO content plan: topic clusters, prioritised keyword map, and ten production-ready content briefs. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 7);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('Programmatic SEO with AI', 'programmatic-seo-with-ai', 'Generate hundreds of useful, templated landing pages from structured data — responsibly — with AI filling the quality gap.', 'Generate hundreds of useful, templated landing pages from structured data — responsibly — with AI filling the quality gap.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'programmatic-seo-with-ai'), 'Where programmatic SEO works — and where it gets penalised', 'where-programmatic-seo-works-and-where-it-gets-penalised', '<p>Welcome to <strong>Programmatic SEO with AI</strong>. This opening lesson sets the foundation for everything that follows in the AI Blogging &amp; SEO track: where programmatic SEO works — and where it gets penalised. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in Google Sheets for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: where programmatic SEO works — and where it gets penalised — explained with worked examples</li><li>A guided walkthrough in Google Sheets</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Finding data-driven page opportunities</em>.</p>', null, 1);
