insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Video Generation Fundamentals', 'ai-video-generation-fundamentals', 'Create short cinematic clips from text and images with Runway, Pika and Luma — and learn what today''s models can and can''t do.', 'Create short cinematic clips from text and images with Runway, Pika and Luma — and learn what today''s models can and can''t do.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-video-generation-fundamentals'), 'The AI video landscape: strengths of each tool', 'the-ai-video-landscape-strengths-of-each-tool', '<p>Welcome to <strong>AI Video Generation Fundamentals</strong>. This opening lesson sets the foundation for everything that follows in the AI Video Generation &amp; Editing track: the AI video landscape: strengths of each tool. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in Runway for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: the AI video landscape: strengths of each tool — explained with worked examples</li><li>A guided walkthrough in Runway</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Text-to-video prompting: shots, motion, camera moves</em>.</p>', null, 1);
