insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'short-form-video-factory'), 'Platform metadata and posting strategy', 'platform-metadata-and-posting-strategy', '<p>In this lesson we focus on <strong>Platform metadata and posting strategy</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in CapCut for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: platform metadata and posting strategy — explained with worked examples</li><li>A guided walkthrough in CapCut</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — produce 15 publish-ready short videos in one batch week, from hook bank to scheduled uploads. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 7);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Avatars & Talking-Head Videos', 'ai-avatars-and-talking-heads', 'Create presenter-style videos with HeyGen and Synthesia avatars for courses, explainers and multilingual sales videos.', 'Create presenter-style videos with HeyGen and Synthesia avatars for courses, explainers and multilingual sales videos.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-avatars-and-talking-heads'), 'Avatar platforms compared: HeyGen, Synthesia and beyond', 'avatar-platforms-compared-heygen-synthesia-and-beyond', '<p>Welcome to <strong>AI Avatars &amp; Talking-Head Videos</strong>. This opening lesson sets the foundation for everything that follows in the AI Video Generation &amp; Editing track: avatar platforms compared: HeyGen, Synthesia and beyond. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in HeyGen for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: avatar platforms compared: HeyGen, Synthesia and beyond — explained with worked examples</li><li>A guided walkthrough in HeyGen</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Scripting for a virtual presenter</em>.</p>', null, 1);
