insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'midjourney-for-designers'), 'Midjourney parameters that matter', 'midjourney-parameters-that-matter', '<p>Welcome to <strong>Midjourney for Designers</strong>. This opening lesson sets the foundation for everything that follows in the AI Graphic Design &amp; Illustration track: midjourney parameters that matter. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in Midjourney for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: midjourney parameters that matter — explained with worked examples</li><li>A guided walkthrough in Midjourney</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Developing a signature style system</em>.</p>', null, 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'midjourney-for-designers'), 'Developing a signature style system', 'developing-a-signature-style-system', '<p>In this lesson we focus on <strong>Developing a signature style system</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Photoshop for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: developing a signature style system — explained with worked examples</li><li>A guided walkthrough in Photoshop</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Style and character references for consistency</em>.</p>', null, 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'midjourney-for-designers'), 'Style and character references for consistency', 'style-and-character-references-for-consistency', '<p>In this lesson we focus on <strong>Style and character references for consistency</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Figma for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: style and character references for consistency — explained with worked examples</li><li>A guided walkthrough in Figma</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Blending, remixing and iterating on winners</em>.</p>', null, 3);
