insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'midjourney-for-designers'), 'From generations to usable brand assets in Figma', 'from-generations-to-usable-brand-assets-in-figma', '<p>In this lesson we focus on <strong>From generations to usable brand assets in Figma</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Figma for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: from generations to usable brand assets in Figma — explained with worked examples</li><li>A guided walkthrough in Figma</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Licensing and commercial use explained</em>.</p>', null, 6);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'midjourney-for-designers'), 'Licensing and commercial use explained', 'licensing-and-commercial-use-explained', '<p>In this lesson we focus on <strong>Licensing and commercial use explained</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Midjourney for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: licensing and commercial use explained — explained with worked examples</li><li>A guided walkthrough in Midjourney</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — create a cohesive 10-asset visual identity set — hero images, patterns, iconography — for a real or fictional brand. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 7);
