insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Illustration: Characters, Scenes & Product Art', 'ai-illustration-for-products', 'Develop consistent illustrated characters and scene art for books, apps and packaging using reference-driven AI workflows.', 'Develop consistent illustrated characters and scene art for books, apps and packaging using reference-driven AI workflows.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-illustration-for-products'), 'Illustration styles and how to specify them', 'illustration-styles-and-how-to-specify-them', '<p>Welcome to <strong>AI Illustration: Characters, Scenes &amp; Product Art</strong>. This opening lesson sets the foundation for everything that follows in the AI Graphic Design &amp; Illustration track: illustration styles and how to specify them. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in Midjourney for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: illustration styles and how to specify them — explained with worked examples</li><li>A guided walkthrough in Midjourney</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Designing a character sheet with AI</em>.</p>', null, 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-illustration-for-products'), 'Designing a character sheet with AI', 'designing-a-character-sheet-with-ai', '<p>In this lesson we focus on <strong>Designing a character sheet with AI</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Leonardo AI for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: designing a character sheet with AI — explained with worked examples</li><li>A guided walkthrough in Leonardo AI</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Keeping characters consistent across scenes</em>.</p>', null, 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-illustration-for-products'), 'Keeping characters consistent across scenes', 'keeping-characters-consistent-across-scenes', '<p>In this lesson we focus on <strong>Keeping characters consistent across scenes</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Procreate for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: keeping characters consistent across scenes — explained with worked examples</li><li>A guided walkthrough in Procreate</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Composition for storytelling panels</em>.</p>', null, 3);
