insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-illustration-for-products'), 'Building a portfolio-ready illustration set', 'building-a-portfolio-ready-illustration-set', '<p>In this lesson we focus on <strong>Building a portfolio-ready illustration set</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Midjourney for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: building a portfolio-ready illustration set — explained with worked examples</li><li>A guided walkthrough in Midjourney</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — create an 8-illustration set featuring one consistent character across different scenes, ready for a children''s book or app. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 7);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Product Photography & Mockups', 'product-photography-with-ai', 'Replace expensive photoshoots: generate studio-grade product shots, lifestyle scenes and ad creatives from a few phone photos.', 'Replace expensive photoshoots: generate studio-grade product shots, lifestyle scenes and ad creatives from a few phone photos.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'product-photography-with-ai'), 'Shooting usable source photos on a phone', 'shooting-usable-source-photos-on-a-phone', '<p>Welcome to <strong>AI Product Photography &amp; Mockups</strong>. This opening lesson sets the foundation for everything that follows in the AI Graphic Design &amp; Illustration track: shooting usable source photos on a phone. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in Photoroom for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: shooting usable source photos on a phone — explained with worked examples</li><li>A guided walkthrough in Photoroom</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Background removal and clean cutouts</em>.</p>', null, 1);
