insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'product-photography-with-ai'), 'Building a reusable product-shot pipeline', 'building-a-reusable-product-shot-pipeline', '<p>In this lesson we focus on <strong>Building a reusable product-shot pipeline</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Photoroom for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: building a reusable product-shot pipeline — explained with worked examples</li><li>A guided walkthrough in Photoroom</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — produce a 12-image product photography set — white background, lifestyle and seasonal campaign shots — from phone photos of a real product. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 7);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Automation with Make.com', 'ai-automation-with-make', 'Connect ChatGPT to your apps with Make: build no-code automations that read, reason and act across your tool stack.', 'Connect ChatGPT to your apps with Make: build no-code automations that read, reason and act across your tool stack.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-automation-with-make'), 'Automation thinking: triggers, actions, routers', 'automation-thinking-triggers-actions-routers', '<p>Welcome to <strong>AI Automation with Make.com</strong>. This opening lesson sets the foundation for everything that follows in the AI Automation &amp; Agents track: automation thinking: triggers, actions, routers. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in Make.com for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: automation thinking: triggers, actions, routers — explained with worked examples</li><li>A guided walkthrough in Make.com</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Your first Make scenario end to end</em>.</p>', null, 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-automation-with-make'), 'Your first Make scenario end to end', 'your-first-make-scenario-end-to-end', '<p>In this lesson we focus on <strong>Your first Make scenario end to end</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in OpenAI API for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: your first Make scenario end to end — explained with worked examples</li><li>A guided walkthrough in OpenAI API</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Adding OpenAI modules: prompts inside workflows</em>.</p>', null, 2);
