insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('Building AI Agents with n8n', 'building-ai-agents-n8n', 'Build agents that plan, use tools and act autonomously — research agents, inbox agents and report writers — on self-hostable n8n.', 'Build agents that plan, use tools and act autonomously — research agents, inbox agents and report writers — on self-hostable n8n.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'building-ai-agents-n8n'), 'Agents vs automations: when each wins', 'agents-vs-automations-when-each-wins', '<p>Welcome to <strong>Building AI Agents with n8n</strong>. This opening lesson sets the foundation for everything that follows in the AI Automation &amp; Agents track: agents vs automations: when each wins. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in n8n for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: agents vs automations: when each wins — explained with worked examples</li><li>A guided walkthrough in n8n</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>n8n setup: cloud and self-hosted</em>.</p>', null, 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'building-ai-agents-n8n'), 'n8n setup: cloud and self-hosted', 'n8n-setup-cloud-and-self-hosted', '<p>In this lesson we focus on <strong>n8n setup: cloud and self-hosted</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in OpenAI API for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: n8n setup: cloud and self-hosted — explained with worked examples</li><li>A guided walkthrough in OpenAI API</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>The AI Agent node: tools, memory, reasoning</em>.</p>', null, 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'building-ai-agents-n8n'), 'The AI Agent node: tools, memory, reasoning', 'the-ai-agent-node-tools-memory-reasoning', '<p>In this lesson we focus on <strong>The AI Agent node: tools, memory, reasoning</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Pinecone for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: the AI Agent node: tools, memory, reasoning — explained with worked examples</li><li>A guided walkthrough in Pinecone</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Giving agents tools: HTTP, search, databases</em>.</p>', null, 3);
