insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'building-ai-agents-n8n'), 'Deploying and monitoring a production agent', 'deploying-and-monitoring-a-production-agent', '<p>In this lesson we focus on <strong>Deploying and monitoring a production agent</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in n8n for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: deploying and monitoring a production agent — explained with worked examples</li><li>A guided walkthrough in n8n</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Scaling to multi-agent workflows</em>.</p>', null, 7);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'building-ai-agents-n8n'), 'Scaling to multi-agent workflows', 'scaling-to-multi-agent-workflows', '<p>In this lesson we focus on <strong>Scaling to multi-agent workflows</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in OpenAI API for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: scaling to multi-agent workflows — explained with worked examples</li><li>A guided walkthrough in OpenAI API</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — deploy a working research-and-report agent that monitors sources, synthesises findings and emails a daily brief. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 8);
