insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'whatsapp-business-automation'), 'Compliance, opt-ins and broadcast done right', 'compliance-opt-ins-and-broadcast-done-right', '<p>In this lesson we focus on <strong>Compliance, opt-ins and broadcast done right</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in WhatsApp Business API for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: compliance, opt-ins and broadcast done right — explained with worked examples</li><li>A guided walkthrough in WhatsApp Business API</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — launch a WhatsApp assistant for a real business that answers FAQs, qualifies leads and hands off to a human cleanly. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 7);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('API-First AI: OpenAI & Gemini Integrations', 'api-first-ai-integrations', 'Go beyond no-code: call OpenAI and Gemini APIs directly, with function calling, structured output and cost control.', 'Go beyond no-code: call OpenAI and Gemini APIs directly, with function calling, structured output and cost control.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'api-first-ai-integrations'), 'API fundamentals: keys, requests, tokens, pricing', 'api-fundamentals-keys-requests-tokens-pricing', '<p>Welcome to <strong>API-First AI: OpenAI &amp; Gemini Integrations</strong>. This opening lesson sets the foundation for everything that follows in the AI Automation &amp; Agents track: aPI fundamentals: keys, requests, tokens, pricing. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in OpenAI API for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: aPI fundamentals: keys, requests, tokens, pricing — explained with worked examples</li><li>A guided walkthrough in OpenAI API</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Chat completions in Postman and code</em>.</p>', null, 1);
