insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'api-first-ai-integrations'), 'Structured output and JSON mode', 'structured-output-and-json-mode', '<p>In this lesson we focus on <strong>Structured output and JSON mode</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Postman for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: structured output and JSON mode — explained with worked examples</li><li>A guided walkthrough in Postman</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Function calling: letting models trigger your code</em>.</p>', null, 3);
