insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'bubble-ai-saas'), 'Launch: from test mode to first customers', 'launch-from-test-mode-to-first-customers', '<p>In this lesson we focus on <strong>Launch: from test mode to first customers</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in OpenAI API for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: launch: from test mode to first customers — explained with worked examples</li><li>A guided walkthrough in OpenAI API</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — launch a functioning AI SaaS MVP with signup, a working AI feature, subscription billing and usage limits. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 8);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Internal Tools with Glide', 'internal-tools-with-glide', 'Turn spreadsheets into polished internal apps with AI columns — inventory, field sales and approval tools your team will use.', 'Turn spreadsheets into polished internal apps with AI columns — inventory, field sales and approval tools your team will use.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'internal-tools-with-glide'), 'From spreadsheet to app in an afternoon', 'from-spreadsheet-to-app-in-an-afternoon', '<p>Welcome to <strong>AI Internal Tools with Glide</strong>. This opening lesson sets the foundation for everything that follows in the No-Code AI Apps track: from spreadsheet to app in an afternoon. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in Glide for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: from spreadsheet to app in an afternoon — explained with worked examples</li><li>A guided walkthrough in Glide</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Data structure: tables, relations, rollups</em>.</p>', null, 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'internal-tools-with-glide'), 'Data structure: tables, relations, rollups', 'data-structure-tables-relations-rollups', '<p>In this lesson we focus on <strong>Data structure: tables, relations, rollups</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Google Sheets for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: data structure: tables, relations, rollups — explained with worked examples</li><li>A guided walkthrough in Google Sheets</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Screens, components and mobile layouts</em>.</p>', null, 2);
