insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'internal-tools-with-glide'), 'Piloting with your team and iterating', 'piloting-with-your-team-and-iterating', '<p>In this lesson we focus on <strong>Piloting with your team and iterating</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Glide for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: piloting with your team and iterating — explained with worked examples</li><li>A guided walkthrough in Glide</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — build and roll out one internal tool for a real workflow — with AI-powered fields, roles and a mobile-friendly UI. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 7);
