insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('Mobile AI Apps with FlutterFlow', 'mobile-ai-apps-flutterflow', 'Design and publish real iOS/Android apps with AI features using FlutterFlow''s visual builder and API integrations.', 'Design and publish real iOS/Android apps with AI features using FlutterFlow''s visual builder and API integrations.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'mobile-ai-apps-flutterflow'), 'FlutterFlow fundamentals and project setup', 'flutterflow-fundamentals-and-project-setup', '<p>Welcome to <strong>Mobile AI Apps with FlutterFlow</strong>. This opening lesson sets the foundation for everything that follows in the No-Code AI Apps track: flutterFlow fundamentals and project setup. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in FlutterFlow for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: flutterFlow fundamentals and project setup — explained with worked examples</li><li>A guided walkthrough in FlutterFlow</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Screens, navigation and design systems</em>.</p>', null, 1);
