insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'mobile-ai-apps-flutterflow'), 'Testing on devices', 'testing-on-devices', '<p>In this lesson we focus on <strong>Testing on devices</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in FlutterFlow for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: testing on devices — explained with worked examples</li><li>A guided walkthrough in FlutterFlow</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Store submission walkthrough</em>.</p>', null, 7);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'mobile-ai-apps-flutterflow'), 'Store submission walkthrough', 'store-submission-walkthrough', '<p>In this lesson we focus on <strong>Store submission walkthrough</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Firebase for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: store submission walkthrough — explained with worked examples</li><li>A guided walkthrough in Firebase</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — build a mobile AI app — camera or chat powered — and produce a signed build ready for store submission. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 8);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('Meta Ads with AI: Creative to Conversion', 'meta-ads-with-ai', 'Plan, produce and scale Facebook & Instagram campaigns with AI-generated creatives, copy variants and structured testing.', 'Plan, produce and scale Facebook & Instagram campaigns with AI-generated creatives, copy variants and structured testing.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'meta-ads-with-ai'), 'Campaign structure that survives algorithm changes', 'campaign-structure-that-survives-algorithm-changes', '<p>Welcome to <strong>Meta Ads with AI: Creative to Conversion</strong>. This opening lesson sets the foundation for everything that follows in the AI for Marketing &amp; Paid Ads track: campaign structure that survives algorithm changes. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in Meta Ads Manager for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: campaign structure that survives algorithm changes — explained with worked examples</li><li>A guided walkthrough in Meta Ads Manager</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Offers and angles: the strategy before the ads</em>.</p>', null, 1);
