insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'influencer-ugc-ai-pipeline'), 'Why UGC outperforms polished ads', 'why-ugc-outperforms-polished-ads', '<p>Welcome to <strong>UGC &amp; Influencer Content with AI</strong>. This opening lesson sets the foundation for everything that follows in the AI for Marketing &amp; Paid Ads track: why UGC outperforms polished ads. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in ChatGPT for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: why UGC outperforms polished ads — explained with worked examples</li><li>A guided walkthrough in ChatGPT</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>UGC script formulas and AI generation</em>.</p>', null, 1);
