insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'helpdesk-copilots'), 'Measuring handle time and quality shifts', 'measuring-handle-time-and-quality-shifts', '<p>In this lesson we focus on <strong>Measuring handle time and quality shifts</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Zendesk AI for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: measuring handle time and quality shifts — explained with worked examples</li><li>A guided walkthrough in Zendesk AI</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — roll out an agent-copilot workflow for a support team: drafted replies, summary macros, QA rubric and measured handle-time impact. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 7);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('Voice AI Agents for Phone Support', 'voice-ai-agents', 'Build phone agents that answer calls, book appointments and route callers using Vapi and Retell — with latency and fallback handled.', 'Build phone agents that answer calls, book appointments and route callers using Vapi and Retell — with latency and fallback handled.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'voice-ai-agents'), 'The voice agent stack: STT, LLM, TTS, telephony', 'the-voice-agent-stack-stt-llm-tts-telephony', '<p>Welcome to <strong>Voice AI Agents for Phone Support</strong>. This opening lesson sets the foundation for everything that follows in the AI Customer Support track: the voice agent stack: STT, LLM, TTS, telephony. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in Vapi for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: the voice agent stack: STT, LLM, TTS, telephony — explained with worked examples</li><li>A guided walkthrough in Vapi</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Designing call flows and conversation states</em>.</p>', null, 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'voice-ai-agents'), 'Designing call flows and conversation states', 'designing-call-flows-and-conversation-states', '<p>In this lesson we focus on <strong>Designing call flows and conversation states</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Retell AI for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: designing call flows and conversation states — explained with worked examples</li><li>A guided walkthrough in Retell AI</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Building your first agent in Vapi</em>.</p>', null, 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'voice-ai-agents'), 'Building your first agent in Vapi', 'building-your-first-agent-in-vapi', '<p>In this lesson we focus on <strong>Building your first agent in Vapi</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Twilio for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: building your first agent in Vapi — explained with worked examples</li><li>A guided walkthrough in Twilio</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Latency, interruptions and barge-in handling</em>.</p>', null, 3);
