insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('Data Analysis with ChatGPT', 'chatgpt-data-analysis', 'Upload spreadsheets and get real analysis: cleaning, exploration, charts and forecasts with ChatGPT''s Advanced Data Analysis.', 'Upload spreadsheets and get real analysis: cleaning, exploration, charts and forecasts with ChatGPT''s Advanced Data Analysis.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'chatgpt-data-analysis'), 'What Advanced Data Analysis can and can''t do', 'what-advanced-data-analysis-can-and-cant-do', '<p>Welcome to <strong>Data Analysis with ChatGPT</strong>. This opening lesson sets the foundation for everything that follows in the AI Data Analysis track: what Advanced Data Analysis can and can''t do. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in ChatGPT for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: what Advanced Data Analysis can and can''t do — explained with worked examples</li><li>A guided walkthrough in ChatGPT</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Preparing and uploading your data safely</em>.</p>', null, 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'chatgpt-data-analysis'), 'Preparing and uploading your data safely', 'preparing-and-uploading-your-data-safely', '<p>In this lesson we focus on <strong>Preparing and uploading your data safely</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Excel for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: preparing and uploading your data safely — explained with worked examples</li><li>A guided walkthrough in Excel</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Cleaning: duplicates, formats, missing values</em>.</p>', null, 2);
