insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('SQL with AI Copilots', 'sql-with-ai-copilots', 'Learn practical SQL faster than any bootcamp — with AI writing, explaining and debugging queries against real databases.', 'Learn practical SQL faster than any bootcamp — with AI writing, explaining and debugging queries against real databases.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'sql-with-ai-copilots'), 'Databases and tables: the mental model', 'databases-and-tables-the-mental-model', '<p>Welcome to <strong>SQL with AI Copilots</strong>. This opening lesson sets the foundation for everything that follows in the AI Data Analysis track: databases and tables: the mental model. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in PostgreSQL for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: databases and tables: the mental model — explained with worked examples</li><li>A guided walkthrough in PostgreSQL</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>SELECT, WHERE, ORDER: your first queries</em>.</p>', null, 1);
