insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'sql-with-ai-copilots'), 'Joins explained until they click', 'joins-explained-until-they-click', '<p>In this lesson we focus on <strong>Joins explained until they click</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in DBeaver for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: joins explained until they click — explained with worked examples</li><li>A guided walkthrough in DBeaver</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Aggregation: GROUP BY and business metrics</em>.</p>', null, 3);
