insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'sql-with-ai-copilots'), 'The analyst''s query library', 'the-analysts-query-library', '<p>In this lesson we focus on <strong>The analyst''s query library</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in ChatGPT for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: the analyst''s query library — explained with worked examples</li><li>A guided walkthrough in ChatGPT</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — answer ten real business questions against a sample commerce database, with documented, optimised queries. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 8);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('BI Dashboards with AI: Power BI & Looker Studio', 'bi-dashboards-ai', 'Build executive dashboards with AI-assisted data modelling, DAX help and natural-language insights in Power BI and Looker Studio.', 'Build executive dashboards with AI-assisted data modelling, DAX help and natural-language insights in Power BI and Looker Studio.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'bi-dashboards-ai'), 'Dashboard strategy: questions before charts', 'dashboard-strategy-questions-before-charts', '<p>Welcome to <strong>BI Dashboards with AI: Power BI &amp; Looker Studio</strong>. This opening lesson sets the foundation for everything that follows in the AI Data Analysis track: dashboard strategy: questions before charts. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in Power BI for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: dashboard strategy: questions before charts — explained with worked examples</li><li>A guided walkthrough in Power BI</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Connecting and modelling data sources</em>.</p>', null, 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'bi-dashboards-ai'), 'Connecting and modelling data sources', 'connecting-and-modelling-data-sources', '<p>In this lesson we focus on <strong>Connecting and modelling data sources</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Looker Studio for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: connecting and modelling data sources — explained with worked examples</li><li>A guided walkthrough in Looker Studio</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>DAX and calculated fields with AI help</em>.</p>', null, 2);
