insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'forecasting-for-business'), 'Forecasting honestly: uncertainty and baselines', 'forecasting-honestly-uncertainty-and-baselines', '<p>Welcome to <strong>AI Forecasting for Business Decisions</strong>. This opening lesson sets the foundation for everything that follows in the AI Data Analysis track: forecasting honestly: uncertainty and baselines. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in ChatGPT for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: forecasting honestly: uncertainty and baselines — explained with worked examples</li><li>A guided walkthrough in ChatGPT</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Decomposing trend and seasonality</em>.</p>', null, 1);
