insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-voiceover-production'), 'The AI voice landscape and licensing', 'the-ai-voice-landscape-and-licensing', '<p>Welcome to <strong>AI Voiceover Production with ElevenLabs</strong>. This opening lesson sets the foundation for everything that follows in the AI Audio &amp; Voice track: the AI voice landscape and licensing. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in ElevenLabs for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: the AI voice landscape and licensing — explained with worked examples</li><li>A guided walkthrough in ElevenLabs</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Choosing and auditioning voices</em>.</p>', null, 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-voiceover-production'), 'Choosing and auditioning voices', 'choosing-and-auditioning-voices', '<p>In this lesson we focus on <strong>Choosing and auditioning voices</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Audacity for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: choosing and auditioning voices — explained with worked examples</li><li>A guided walkthrough in Audacity</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Writing for the ear: scripts that speak well</em>.</p>', null, 2);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-voiceover-production'), 'Writing for the ear: scripts that speak well', 'writing-for-the-ear-scripts-that-speak-well', '<p>In this lesson we focus on <strong>Writing for the ear: scripts that speak well</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in CapCut for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: writing for the ear: scripts that speak well — explained with worked examples</li><li>A guided walkthrough in CapCut</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Directing delivery: pacing, emphasis, emotion</em>.</p>', null, 3);
