insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-voiceover-production'), 'Cleanup and mastering in Audacity', 'cleanup-and-mastering-in-audacity', '<p>In this lesson we focus on <strong>Cleanup and mastering in Audacity</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in CapCut for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: cleanup and mastering in Audacity — explained with worked examples</li><li>A guided walkthrough in CapCut</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Syncing voiceover to video</em>.</p>', null, 6);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-voiceover-production'), 'Syncing voiceover to video', 'syncing-voiceover-to-video', '<p>In this lesson we focus on <strong>Syncing voiceover to video</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in ElevenLabs for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: syncing voiceover to video — explained with worked examples</li><li>A guided walkthrough in ElevenLabs</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — produce three finished voiceover assets: a 30-second ad read, a 2-minute explainer and a course module intro — mixed and mastered. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 7);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('Podcast Production with AI', 'podcast-production-ai', 'Launch and run a podcast with AI handling planning, show notes, editing, clips and distribution — sustainably, every week.', 'Launch and run a podcast with AI handling planning, show notes, editing, clips and distribution — sustainably, every week.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'podcast-production-ai'), 'Show strategy: premise, format, audience', 'show-strategy-premise-format-audience', '<p>Welcome to <strong>Podcast Production with AI</strong>. This opening lesson sets the foundation for everything that follows in the AI Audio &amp; Voice track: show strategy: premise, format, audience. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in Riverside for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: show strategy: premise, format, audience — explained with worked examples</li><li>A guided walkthrough in Riverside</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Recording setups that sound professional</em>.</p>', null, 1);
