insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-dubbing-translation'), 'The dubbing opportunity for creators and brands', 'the-dubbing-opportunity-for-creators-and-brands', '<p>Welcome to <strong>AI Dubbing &amp; Audio Translation</strong>. This opening lesson sets the foundation for everything that follows in the AI Audio &amp; Voice track: the dubbing opportunity for creators and brands. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in ElevenLabs Dubbing for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: the dubbing opportunity for creators and brands — explained with worked examples</li><li>A guided walkthrough in ElevenLabs Dubbing</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>How AI dubbing and voice cloning work</em>.</p>', null, 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-dubbing-translation'), 'How AI dubbing and voice cloning work', 'how-ai-dubbing-and-voice-cloning-work', '<p>In this lesson we focus on <strong>How AI dubbing and voice cloning work</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in HeyGen for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: how AI dubbing and voice cloning work — explained with worked examples</li><li>A guided walkthrough in HeyGen</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Preparing source video and clean audio</em>.</p>', null, 2);
