insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-dubbing-translation'), 'Subtitles and captions alongside dubs', 'subtitles-and-captions-alongside-dubs', '<p>In this lesson we focus on <strong>Subtitles and captions alongside dubs</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in CapCut for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: subtitles and captions alongside dubs — explained with worked examples</li><li>A guided walkthrough in CapCut</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Quality review with native speakers</em>.</p>', null, 6);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'ai-dubbing-translation'), 'Quality review with native speakers', 'quality-review-with-native-speakers', '<p>In this lesson we focus on <strong>Quality review with native speakers</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in ElevenLabs Dubbing for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: quality review with native speakers — explained with worked examples</li><li>A guided walkthrough in ElevenLabs Dubbing</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — dub a real 5-minute video into two target languages with timed, voice-matched audio and corrected subtitles. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 7);
