insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'voice-cloning-ethics-and-practice'), 'Disclosure and trust with your audience', 'disclosure-and-trust-with-your-audience', '<p>In this lesson we focus on <strong>Disclosure and trust with your audience</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in ElevenLabs for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: disclosure and trust with your audience — explained with worked examples</li><li>A guided walkthrough in ElevenLabs</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — create your own professional voice clone with a documented consent/usage policy, and produce three content pieces with it. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 7);
insert into public.courses (title, slug, summary, description, category, price_ngn, duration, image, is_published, level, is_featured, tools, project) values ('AI Music & Sound Design for Content', 'music-and-sound-design-ai', 'Create custom music beds, jingles and sound design for videos and podcasts with Suno and Udio — and stay on the right side of licensing.', 'Create custom music beds, jingles and sound design for videos and podcasts with Suno and Udio — and stay on the right side of licensing.
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'music-and-sound-design-ai'), 'AI music tools and what they''re good at', 'ai-music-tools-and-what-theyre-good-at', '<p>Welcome to <strong>AI Music &amp; Sound Design for Content</strong>. This opening lesson sets the foundation for everything that follows in the AI Audio &amp; Voice track: aI music tools and what they''re good at. Before touching any tool, you''ll build the mental model that separates people who get lucky results from people who get repeatable ones.</p><p>You''ll work primarily in Suno for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: aI music tools and what they''re good at — explained with worked examples</li><li>A guided walkthrough in Suno</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Prompting genres, moods and structures</em>.</p>', null, 1);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'music-and-sound-design-ai'), 'Prompting genres, moods and structures', 'prompting-genres-moods-and-structures', '<p>In this lesson we focus on <strong>Prompting genres, moods and structures</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Udio for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: prompting genres, moods and structures — explained with worked examples</li><li>A guided walkthrough in Udio</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Jingles and sonic branding</em>.</p>', null, 2);
