insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'music-and-sound-design-ai'), 'Sound effects and transitions', 'sound-effects-and-transitions', '<p>In this lesson we focus on <strong>Sound effects and transitions</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Udio for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: sound effects and transitions — explained with worked examples</li><li>A guided walkthrough in Udio</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Licensing and commercial use rules</em>.</p>', null, 5);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'music-and-sound-design-ai'), 'Licensing and commercial use rules', 'licensing-and-commercial-use-rules', '<p>In this lesson we focus on <strong>Licensing and commercial use rules</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in CapCut for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: licensing and commercial use rules — explained with worked examples</li><li>A guided walkthrough in CapCut</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Next up</h3><p>Complete the practice exercise, mark this lesson as done, and continue to <em>Mixing music into your content</em>.</p>', null, 6);
insert into public.lessons (course_id, title, slug, content, video_url, position) values ((select id from public.courses where slug = 'music-and-sound-design-ai'), 'Mixing music into your content', 'mixing-music-into-your-content', '<p>In this lesson we focus on <strong>Mixing music into your content</strong>. It builds directly on what you''ve done so far, and the exercise at the end feeds into your capstone project, so keep your working files from previous lessons open.</p><p>You''ll work primarily in Suno for this lesson. We walk through the workflow step by step on a realistic scenario, flag the mistakes that cost beginners the most time, and show you how professionals verify their output before shipping it. Pause at each checkpoint and reproduce the result yourself — the skill is in your hands, not your notes.</p><h3>In this lesson</h3><ul><li>The core idea: mixing music into your content — explained with worked examples</li><li>A guided walkthrough in Suno</li><li>Common pitfalls and how to recover from them</li><li>A practice exercise with a model answer to compare against</li></ul><h3>Wrapping up the lessons</h3><p>That completes the taught portion of the course. Next up: the final assessment, and your capstone project — produce a complete audio brand kit: intro jingle, three music beds, and a sound-design pass on one real video. Review your exercise files from each lesson; they''re the building blocks of your submission.</p>', null, 7);
insert into public.testimonials (name, role, quote, course_id) values ('Adaeze Okonkwo', 'Freelance Copywriter, Lagos', 'I finished AI Copywriting Essentials on a Saturday and closed my first retainer client the following week. The de-robotting edit lesson alone was worth the fee — my drafts finally sound like me, just faster.', (select id from public.courses where slug = 'ai-copywriting-essentials'));
insert into public.testimonials (name, role, quote, course_id) values ('Ibrahim Musa', 'Operations Manager, Kano', 'The Make.com course paid for itself in the first month. We automated our order confirmations and lead follow-ups, and I didn''t write a single line of code. The capstone project is now running live in our business.', (select id from public.courses where slug = 'ai-automation-with-make'));
insert into public.testimonials (name, role, quote, course_id) values ('Funmilayo Adeyemi', 'Content Creator, Ibadan', 'Faceless YouTube Channels gave me an actual production system, not motivation fluff. Three months after my capstone, my channel crossed 8,000 subscribers and I run everything in about six hours a week.', (select id from public.courses where slug = 'faceless-youtube-channels'));
insert into public.testimonials (name, role, quote, course_id) values ('Chidi Nwankwo', 'Data Analyst, Abuja', 'SQL with AI Copilots is how SQL should be taught. The AI pair-programming approach meant I was never stuck for more than a minute, and the certificate verification link went straight on my CV.', (select id from public.courses where slug = 'sql-with-ai-copilots'));
insert into public.testimonials (name, role, quote, course_id) values ('Amina Bello', 'Customer Success Lead, Port Harcourt', 'We deployed the support chatbot from my capstone project and our ticket volume dropped by half. My manager asked where I learned it — I just sent her the certificate verification link.', (select id from public.courses where slug = 'ai-support-chatbots'));
insert into public.testimonials (name, role, quote, course_id) values ('Tunde Bakare', 'Founder, Lagos', 'I built and launched my first AI web app with the Lovable course in under two weeks. As a non-technical founder, shipping something real — auth, database and all — felt impossible before this.', (select id from public.courses where slug = 'build-ai-apps-with-lovable'));
insert into public.testimonials (name, role, quote, course_id) values ('Ngozi Eze', 'Digital Marketer, Enugu', 'The Meta Ads course is taught by people who clearly run ads. The creative testing system cut our cost per lead by 40%, and the AI creative pipeline means we never run out of fresh angles.', (select id from public.courses where slug = 'meta-ads-with-ai'));
insert into public.testimonials (name, role, quote, course_id) values ('Suleiman Abdullahi', 'Voiceover Artist, Kaduna', 'I was afraid AI would replace my voice work. The ElevenLabs course showed me how to scale it instead — I now deliver projects in three languages and my turnaround went from days to hours.', (select id from public.courses where slug = 'ai-voiceover-production'));
